   <div className="panel-card analysis-chart"><div className="analysis-chart-head"><b>Speed vs time</b><span>m/s · seconds</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={samples}><CartesianGrid stroke="#25354b" strokeDasharray="3 3"/><XAxis dataKey="t" tick={{fill:'#8192aa',fontSize:10}}/><YAxis tick={{fill:'#8192aa',fontSize:10}}/><Tooltip contentStyle={{background:'#111d2c',border:'1px solid #34445b',borderRadius:8,color:'#e9eef7'}}/><ChartLine type="monotone" dataKey="speed" name="speed" stroke="#f0b779" dot={false} strokeWidth={2}/></LineChart></ResponsiveContainer></div></div>
